const mangayomiSources = [
  {
    id: 16283412,
    name: "kone",
    lang: "ko",
    baseUrl: "https://kone.gg",
    version: "1.0.3",
    isNsfw: true,
    additionalParams: "{\"board\":\"lolita\",\"category\":\"cIgVZ8ye_xLuX86NSCnjWb\"}",
    sourceCodeUrl: "https://raw.githubusercontent.com/sosoies/repo/main/src/ko/kone.min.js",
    iconUrl: "https://www.google.com/s2/favicons?sz=256&domain=https://kone.gg",
    apiUrl: ""
  }
];

const attr = (t, e) => String(t?.attr(e) || "").trim(),
  text = (t) => String(t?.text || "").trim(),
  utf8 = (t) => {
    if (/[^\x00-\xff]/.test(t)) return t;
    try {
      return decodeURIComponent(
        t
          .replace(/[%\x80-\xff]/g, (t) => "%" + t.charCodeAt(0).toString(16).padStart(2, "0"))
      );
    } catch (e) {
      return t;
    }
  };

class DefaultExtension extends MProvider {
  get supportsLatest() {
    return true;
  }
  pref(t) {
    try {
      return String((new SharedPreferences).get(t) || "").trim();
    } catch (t) {
      return "";
    }
  }
  get params() {
    // 💡 저장된 설정값이 있더라도 강제로 원하는 값으로 고정하고 싶다면 여기서 직접 반환합니다.
    // 만약 사용자가 수동으로 설정한 값을 살리고 싶다면 아래 리턴값을 수정하세요.
    return {
      board: "lolita",
      category: "cIgVZ8ye_xLuX86NSCnjWb"
    };
  }
  get board() {
    const { board: t } = this.params;
    if (!/^[A-Za-z0-9_-]+$/.test(t)) throw new Error("올바른 Kone 게시판 ID가 아닙니다.");
    return `/s/${t}`;
  }
  get category() {
    const { category: t } = this.params;
    if (!/^[A-Za-z0-9_-]+$/.test(t)) throw new Error("올바른 Kone 카테고리 ID가 아닙니다.");
    return t;
  }
  getSourcePreferences() {
    return [
      {
        key: "board",
        editTextPreference: {
          title: "게시판 ID",
          summary: "주소의 /s/<ID> 부분",
          value: "lolita",
          dialogTitle: "게시판 ID",
          dialogMessage: "예: lolita",
        },
      },
      {
        key: "category",
        editTextPreference: {
          title: "카테고리 ID",
          summary: "주소의 category= 값",
          value: "cIgVZ8ye_xLuX86NSCnjWb",
          dialogTitle: "카테고리 ID",
          dialogMessage: "예: cIgVZ8ye_xLuX86NSCnjWb",
        },
      },
    ];
  }
  getHeaders() {
    return { "User-Agent": "Mozilla/5.0", Referer: "https://kone.gg/" };
  }
  postPath(t) {
    const e = String(t)
      .replace(/&amp;/g, "&")
      .replace(/^https:\/\/kone\.gg(?=\/)/, "")
      .split(/[?#]/)[0];
    if (!/^\/s\/[A-Za-z0-9_-]+\/[A-Za-z0-9_-]+$/.test(e)) throw new Error("Kone 게시글 주소가 아닙니다.");
    return e;
  }
  imageUrl(t) {
    const e = attr(t, "src");
    return /^https:\/\/[^\s\\]+$/.test(e) ? e : "";
  }
  async document(t) {
    const e = this._client || (this._client = new Client({ timeout: 20, connectTimeout: 5 })),
      r = await e.get(this.source.baseUrl + t, this.getHeaders());
    if (200 !== r.statusCode) throw new Error(`Kone 요청에 실패했습니다 (HTTP ${r.statusCode}).`);
    if (/<title>\s*Just a moment|id=["']cf-chl/i.test(r.body))
      throw new Error("WebView에서 사이트 인증을 완료한 후 다시 시도해 주세요.");
    return new Document(utf8(r.body).replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, "")).body;
  }
  async list(t, e = "") {
    if (!Number.isSafeInteger(t) || t < 1) throw new Error("올바른 페이지 번호가 아닙니다.");
    const r = this.board,
      s = this.category,
      a = String(e || "").trim().slice(0, 128),
      i = await this.document(`${r}?category=${s}&p=${t}${a ? "&q=" + encodeURIComponent(a) : ""}`),
      o = new Map();
    for (const t of i.select('a[class*="group/article"]')) {
      if (t.selectFirst(".lucide-pin")?.className) continue;
      const e = attr(t.selectFirst("div[title]"), "title");
      if (!e) continue;
      let s;
      try {
        s = this.postPath(attr(t, "href"));
      } catch (t) {
        continue;
      }
      if (!s.startsWith(r + "/")) continue;
      const a = this.imageUrl(t.select("img").find((t) => attr(t, "alt") === e));
      o.has(s) || o.set(s, { name: e, link: s, imageUrl: a });
    }
    const n = i.select("a[href]").some((e) => {
      const r = attr(e, "href").replace(/&amp;/g, "&");
      return r.includes(`category=${s}`) && new RegExp(`[?&]p=${t + 1}(?:&|$)`).test(r);
    });
    return { list: [...o.values()], hasNextPage: n };
  }
  getPopular(t) {
    return this.list(t);
  }
  getLatestUpdates(t) {
    return this.list(t);
  }
  search(t, e) {
    return this.list(e, t);
  }
  getFilterList() {
    return [];
  }
  images(t) {
    return [...new Set(t.select(".article-prose .image-view-wrapper img").map((t) => this.imageUrl(t)).filter(Boolean))];
  }
  async getDetail(t) {
    const e = this.postPath(t),
      r = await this.document(e),
      s = text(r.selectFirst("header h1"));
    if (!s) throw new Error("게시글을 찾을 수 없습니다. 삭제 또는 접근 제한 여부를 확인해 주세요.");
    return {
      name: s,
      link: e,
      imageUrl: this.images(r)[0] || "",
      status: 1,
      author: attr(r.selectFirst('header a[aria-label][href^="/u/"]'), "aria-label"),
      description: text(r.selectFirst(".article-prose")).slice(0, 1e3),
      chapters: [{ name: s, url: e }],
    };
  }
  async getPageList(t) {
    const e = this.images(await this.document(this.postPath(t)));
    if (!e.length) throw new Error("게시글 본문에 표시할 이미지가 없습니다.");
    return e.map((t) => ({ url: t, headers: this.getHeaders() }));
  }
}
